insert into section_rich_text (section_id, body_text) values ('sec_cobalt_about', 'Cobalt The Restaurant offers waterfront fine dining in Orange Beach, Alabama, featuring the freshest Gulf seafood, hand-crafted cocktails, stone hearth pizzas, and an extensive wine list. From signature dishes like Gulf Shrimp & Grits and our famous Crab Bisque to hand-cut steaks and Sunday Brunch, every visit is an unforgettable coastal dining experience.');
